document.addEventListener('DOMContentLoaded', () => {
  const heading = document.querySelector('.tool-experience-heading');
  if (!heading || document.querySelector('.evm-flow')) return;
  const description = heading.querySelector('p');
  if (description) description.textContent = 'Choose a supported network, select a community, and route every eligible swap with purpose.';
  heading.insertAdjacentHTML('afterend', `<section class="evm-flow" aria-label="How EVM Swap works"><div><b>01</b><strong>Choose Network</strong><span>Ethereum, Base, or Polygon.</span></div><div><b>02</b><strong>Choose Community</strong><span>Available recipients update by network.</span></div><div><b>03</b><strong>Set Tokens + Fee</strong><span>Trade with a 0.3–3% platform fee.</span></div><div><b>04</b><strong>Review + Swap</strong><span>Unavailable routes disable confirmation.</span></div></section><div class="evm-network-note"><span>SUPPORTED NETWORKS</span><div><strong>Ethereum</strong><strong>Base</strong><strong>Polygon</strong></div><p>MetaMask, Phantom, and Solflare have been tested. Select the network you want to use before searching for tokens.</p></div>`);
});
